-- Function: public.sp_close_end_of_day_activities
-- Backup generated on 2026-10-25 20:33:49

CREATE OR REPLACE PROCEDURE public.sp_close_end_of_day_activities(IN p_tenant_id uuid, IN p_schedule_ids uuid[], IN p_end_time time without time zone)  LANGUAGE plpgsql AS $procedure$ BEGIN     UPDATE experience_schedules     SET status = 'Completed',         preparation_notes = CASE WHEN preparation_notes IS NULL OR preparation_notes = '' THEN 'System Auto-Closed at End of Day'                                  WHEN preparation_notes LIKE '%System Auto-Closed%' THEN preparation_notes                                  ELSE preparation_notes || ' [System Auto-Closed]' END,         updated_at = CURRENT_TIMESTAMP     WHERE id = ANY(p_schedule_ids);      UPDATE experience_sessions     SET status = 'Completed', end_time = p_end_time,         actual_notes = CASE WHEN actual_notes IS NULL OR actual_notes = '' THEN 'System Auto-Closed at End of Day'                             WHEN actual_notes LIKE '%System Auto-Closed%' THEN actual_notes                             ELSE actual_notes || ' [System Auto-Closed]' END,         updated_at = CURRENT_TIMESTAMP     WHERE tenant_id = p_tenant_id       AND experience_schedule_id = ANY(p_schedule_ids)       AND status NOT IN ('Completed', 'Cancelled', 'Finished'); END; $procedure$ ;
